2000  /**
  2001   * xmlSAX2StartElementNs:
  2002   * @ctx:  the user data (XML parser context)
  2003   * @localname:  the local name of the element
  2004   * @prefix:  the element namespace prefix if available
  2005   * @URI:  the element namespace name if available
  2006   * @nb_namespaces:  number of namespace definitions on that node
  2007   * @namespaces:  pointer to the array of prefix/URI pairs namespace definitions
  2008   * @nb_attributes:  the number of attributes on that node
  2009   * @nb_defaulted:  the number of defaulted attributes.
  2010   * @attributes:  pointer to the array of (localname/prefix/URI/value/end)
  2011   *               attribute values.
  2012   *
  2013   * SAX2 callback when an element start has been detected by the parser.
  2014   * It provides the namespace information for the element, as well as
  2015   * the new namespace declarations on the element.
  2016   */
  2017  void
  2018  xmlSAX2StartElementNs(void *ctx,
  2019                        const xmlChar *localname,
  2020                        const xmlChar *prefix,
  2021                        const xmlChar *URI,
  2022                        int nb_namespaces,
  2023                        const xmlChar **namespaces,
  2024                        int nb_attributes,
  2025                        int nb_defaulted,
  2026                        const xmlChar **attributes)
  2027  {
  2028      xmlParserCtxtPtr ctxt = (xmlParserCtxtPtr) ctx;
  2029      xmlNodePtr ret;
  2030      xmlNodePtr parent;
  2031      xmlNsPtr last = NULL, ns;
  2032      const xmlChar *uri, *pref;
  2033      xmlChar *lname = NULL;
  2034      int i, j;
  2035
  2036      if (ctx == NULL) return;
  2037      /*
  2038       * First check on validity:
  2039       */
  2040      if (ctxt->validate && (ctxt->myDoc->extSubset == NULL) &&
  2041          ((ctxt->myDoc->intSubset == NULL) ||
  2042           ((ctxt->myDoc->intSubset->notations == NULL) &&
  2043            (ctxt->myDoc->intSubset->elements == NULL) &&
  2044            (ctxt->myDoc->intSubset->attributes == NULL) &&
  2045            (ctxt->myDoc->intSubset->entities == NULL)))) {
  2046          xmlErrValid(ctxt, XML_DTD_NO_DTD,
  2047            "Validation failed: no DTD found !", NULL, NULL);
  2048          ctxt->validate = 0;
  2049      }
  2050
  2051      /*
  2052       * Take care of the rare case of an undefined namespace prefix
  2053       */
  2054      if ((prefix != NULL) && (URI == NULL)) {
  2055          if (ctxt->dictNames) {
  2056              const xmlChar *fullname;
  2057
  2058              fullname = xmlDictQLookup(ctxt->dict, prefix, localname);
  2059              if (fullname == NULL) {
  2060                  xmlSAX2ErrMemory(ctxt);
  2061                  return;
  2062              }
  2063              localname = fullname;
  2064          } else {
  2065              lname = xmlBuildQName(localname, prefix, NULL, 0);
  2066              if (lname == NULL) {
  2067                  xmlSAX2ErrMemory(ctxt);
  2068                  return;
  2069              }
  2070          }
  2071      }
  2072      /*
  2073       * allocate the node
  2074       */
  2075      if (ctxt->freeElems != NULL) {
  2076          ret = ctxt->freeElems;
  2077          ctxt->freeElems = ret->next;
  2078          ctxt->freeElemsNr--;
  2079          memset(ret, 0, sizeof(xmlNode));
  2080          ret->doc = ctxt->myDoc;
  2081          ret->type = XML_ELEMENT_NODE;
  2082
  2083          if (ctxt->dictNames)
  2084              ret->name = localname;
  2085          else {
  2086              if (lname == NULL)
  2087                  ret->name = xmlStrdup(localname);
  2088              else
  2089                  ret->name = lname;
  2090              if (ret->name == NULL) {
  2091                  xmlSAX2ErrMemory(ctxt);
  2092                  xmlFree(ret);
  2093                  return;
  2094              }
  2095          }
  2096          if ((__xmlRegisterCallbacks) && (xmlRegisterNodeDefaultValue))
  2097              xmlRegisterNodeDefaultValue(ret);
  2098      } else {
  2099          if (ctxt->dictNames)
  2100              ret = xmlNewDocNodeEatName(ctxt->myDoc, NULL,
  2101                                         (xmlChar *) localname, NULL);
  2102          else if (lname == NULL)
  2103              ret = xmlNewDocNode(ctxt->myDoc, NULL, localname, NULL);
  2104          else
  2105              ret = xmlNewDocNodeEatName(ctxt->myDoc, NULL,
  2106                                         (xmlChar *) lname, NULL);
  2107          if (ret == NULL) {
  2108              xmlSAX2ErrMemory(ctxt);
  2109              return;
  2110          }
  2111      }
  2112      if (ctxt->linenumbers) {
  2113          if (ctxt->input != NULL) {
  2114              if ((unsigned) ctxt->input->line < (unsigned) USHRT_MAX)
  2115                  ret->line = ctxt->input->line;
  2116              else
  2117                  ret->line = USHRT_MAX;
  2118          }
  2119      }
  2120
  2121      /*
  2122       * Build the namespace list
  2123       */
  2124      for (i = 0,j = 0;j < nb_namespaces;j++) {
  2125          pref = namespaces[i++];
  2126          uri = namespaces[i++];
  2127          ns = xmlNewNs(NULL, uri, pref);
  2128          if (ns != NULL) {
  2129              if (last == NULL) {
  2130                  ret->nsDef = last = ns;
  2131              } else {
  2132                  last->next = ns;
  2133                  last = ns;
  2134              }
  2135              if ((URI != NULL) && (prefix == pref))
  2136                  ret->ns = ns;
  2137          } else {
  2138              xmlSAX2ErrMemory(ctxt);
  2139              continue;
  2140          }
  2141
  2142          xmlParserNsUpdateSax(ctxt, pref, ns);
  2143
  2144  #ifdef LIBXML_VALID_ENABLED
  2145          if ((!ctxt->html) && ctxt->validate && ctxt->wellFormed &&
  2146              ctxt->myDoc && ctxt->myDoc->intSubset) {
  2147              ctxt->valid &= xmlValidateOneNamespace(&ctxt->vctxt, ctxt->myDoc,
  2148                                                     ret, prefix, ns, uri);
  2149          }
  2150  #endif /* LIBXML_VALID_ENABLED */
  2151      }
  2152      ctxt->nodemem = -1;
  2153
  2154      /* Initialize parent before pushing node */
  2155      parent = ctxt->node;

